param(
    [string]$RepoRoot = "."
)

$ErrorActionPreference = "Stop"
Set-StrictMode -Version Latest

$ExpectedHead = "8181d2820edd50e9abd4cada30a272c6184d8040"
$InstallerPath = "scripts/apply-bl-mvp-072-study-session-start.ps1"

function Fail([string]$Message) {
    throw "BL-MVP-072 apply: $Message"
}

function Normalize-Lf([string]$Value) {
    return ($Value -replace "`r`n", "`n" -replace "`r", "`n")
}

function Write-Utf8Lf([string]$RelativePath, [string]$Content) {
    $full = Join-Path $script:Root $RelativePath
    $directory = Split-Path -Parent $full
    if (-not (Test-Path $directory)) {
        New-Item -ItemType Directory -Path $directory -Force | Out-Null
    }

    $normalized = Normalize-Lf $Content
    if (-not $normalized.EndsWith("`n")) {
        $normalized += "`n"
    }

    $utf8 = New-Object System.Text.UTF8Encoding($false)
    [System.IO.File]::WriteAllText($full, $normalized, $utf8)
    Write-Host "OK: $RelativePath"
}

function Write-Base64File([string]$RelativePath, [string]$Encoded) {
    $bytes = [Convert]::FromBase64String($Encoded)
    $content = [Text.Encoding]::UTF8.GetString($bytes)
    Write-Utf8Lf $RelativePath $content
}

function Replace-Exact(
    [string]$RelativePath,
    [string]$Old,
    [string]$New,
    [string]$Description
) {
    $full = Join-Path $script:Root $RelativePath
    if (-not (Test-Path $full -PathType Leaf)) {
        Fail "no existe $RelativePath."
    }

    $text = Normalize-Lf ([System.IO.File]::ReadAllText($full))
    $oldLf = Normalize-Lf $Old
    $newLf = Normalize-Lf $New

    if ($text.Contains($newLf)) {
        Write-Host "OK: $Description ya aplicado."
        return
    }

    $count = ([regex]::Matches($text, [regex]::Escape($oldLf))).Count
    if ($count -ne 1) {
        Fail "se esperaba una coincidencia para $Description en $RelativePath; encontradas=$count."
    }

    Write-Utf8Lf $RelativePath ($text.Replace($oldLf, $newLf))
    Write-Host "OK: $Description aplicado."
}

$script:Root = (Resolve-Path $RepoRoot).Path
Set-Location $script:Root

$branch = (& git.exe branch --show-current).Trim()
if ($LASTEXITCODE -ne 0 -or $branch -ne "main") {
    Fail "se requiere branch main; actual='$branch'."
}

$head = (& git.exe rev-parse HEAD).Trim()
if ($LASTEXITCODE -ne 0 -or $head -ne $ExpectedHead) {
    Fail "HEAD esperado $ExpectedHead; actual=$head."
}

$status = @(& git.exe status --porcelain=v1 --untracked-files=all)
if ($LASTEXITCODE -ne 0) {
    Fail "no fue posible leer git status."
}

$unexpected = @(
    $status | Where-Object {
        $path = $_.Substring(3).Trim('"').Replace('\', '/')
        $path -ne $InstallerPath
    }
)

if ($unexpected.Count -gt 0) {
    Write-Host "Cambios locales no esperados:" -ForegroundColor Yellow
    $unexpected | ForEach-Object { Write-Host $_ }
    Fail "el árbol debe estar limpio antes de aplicar BL072."
}

Write-Host "Base verificada: main @ $head"


Write-Base64File "src/Modules/Learning/Infrastructure/Sessions/StudySessionStartService.cs" ""


